  const queues = new WeakMap();
  function storageOperation(storage, key, operation) {
   let keys = queues.get(storage);
   if (!keys) queues.set(storage, keys = new Map());
   const next = (keys.get(key) ?? Promise.resolve()).catch(() => {}).then(operation);
   keys.set(key, next);
   // Remove completed queues without leaving an unhandled rejected promise.
   const clear = () => { if (keys.get(key) === next) keys.delete(key); };
   next.then(clear, clear);
   return next;
  }

