  const MODULE_NAME = "GoDiceLibrary";

  class Utils {
   constructor(context) {
    this.context = context;
    // Preserve the receiver when helpers are passed as callbacks.
    for (const name of Object.getOwnPropertyNames(Utils.prototype)) {
     if (name !== "constructor") this[name] = this[name].bind(this);
    }
   }


  	openConnectionDialog() {
  		const newDice = this.context.createDevice();
  		newDice.requestDevice().catch(error => console.warn('GoDice connection failed:', error));
  	}

   getLinkedDice() {
    return new Map([...this.context.reloadedDice, ...this.context.disconnectedDice, ...this.context.connectedDice]);
   }

   saveDices() {
    // Include linked dice awaiting reconnection as well as currently connected dice.
    const linked = this.getLinkedDice();
    // A failed read must not turn an unknown saved list into an empty snapshot.
    if (!this.context.storageLoaded && linked.size === 0) return Promise.resolve();
    const records = [];
    for (const [id, die] of linked) {
     if (die.reconnect === false) continue;
     records.push({ id, type: die.getDieType(true), color: die.getDieColor(true) });
    }
    const snapshot = JSON.stringify(records);
    return storageOperation(this.context.storage, this.context.storageKey,
     () => this.context.storage.setItem(this.context.storageKey, snapshot))
     .catch(error => console.warn('GoDice could not save linked dice:', error));
   }

   async LoadStoredInfos() {
    try {
     const stored = await storageOperation(this.context.storage, this.context.storageKey,
      () => this.context.storage.getItem(this.context.storageKey));
     this.context.assertActive();
     const records = JSON.parse(stored ?? '[]');
     if (!Array.isArray(records)) throw new Error('Invalid linked dice list');
     this.context.storageLoaded = true;
     const seen = new Set();
     for (const record of records) {
      if (!record || typeof record.id !== 'string' || !record.id || seen.has(record.id) || !Object.hasOwn(GoDice.diceTypes, record.type)) continue;
      seen.add(record.id);
      const die = this.context.createDevice();
      die.diceId = record.id;
      die.setDieType(record.type);
      if (Object.hasOwn(die.diceColour, record.color)) die.dieColor = die.diceColour[record.color];
      this.context.reloadedDice.set(record.id, die);
     }
    } catch (error) { if (error.code === 'GODICE_CANCELLED') throw error; console.warn('GoDice could not restore linked dice:', error); }
   }

  	disconnectAll() {
  		if (this.context.connectedDice) {
  			this.context.connectedDice.forEach((diceInstance, diceId) => {
  				this.disconnectDice(diceId);
  			});
  		}
  		else {
  			console.log("No dice connected");
  		}
  	}

  	disconnectDice(diceId) {
  		console.log("Disconnect:", diceId);
  		const die = this.context.connectedDice.get(diceId) ?? this.context.disconnectedDice.get(diceId) ?? this.context.reloadedDice.get(diceId);
          if (!die) return;
          die.dispose();
          this.context.connectedDice.delete(diceId);
          this.context.disconnectedDice.delete(diceId);
          this.context.reloadedDice.delete(diceId);
          this.saveDices();

          this.context.dicebar.render();
  	}
  	
  	reconnectDice(){
  		if(this.context.disconnectedDice) {
  			this.context.disconnectedDice.forEach((dieInstance, dieId) => {
  				try {
  					console.debug("Reconnecting device ", dieId);
  					Promise.resolve(dieInstance.reconnectDevice()).catch(error => console.warn('GoDice reconnect failed:', error));
  				} catch (err) {
  					console.log("Exception Reconnecting Die.", dieId, err);
  					this.context.disconnectedDice.delete(dieId);
  				}
  			});
  		}
  	}
  	
  	reconnectLoadedDice(){
  		if(this.context.reloadedDice) {
  			this.context.reloadedDice.forEach((dieInstance, dieId) => {
  				try {
  					console.debug("Reconnecting device ", dieId);
  					Promise.resolve(dieInstance.reconnectDevice()).catch(error => console.warn('GoDice reconnect failed:', error));
  				} catch (err) {
  					console.log("Exception Reconnecting Die.", dieId, err);
  					this.context.reloadedDice.delete(dieId);
  				}
  			});
  		}
  	}

  	getModulePath() {
  		let script = Array.from(document.getElementsByTagName("script")).filter((script) => { return script.src.includes(MODULE_NAME)});
  		let fullPath = (script && script.length>0)?script[0].src:null;
  		let path = fullPath?fullPath.substring(0,fullPath.lastIndexOf(MODULE_NAME)+MODULE_NAME.length+1):"/";
  		console.debug("Module path: ", path);
  		return path;
  	}
  	
  	unfulfilledRollsEnabled(){
  		return game.modules.get("unfulfilled-rolls")?.active ? true : false;
  	}

  	htmlToElement(html) {
  		var template = document.createElement('template');
  		html = html.trim();
  		template.innerHTML = html;
  		return template.content.firstChild;
  	}

  	findSpeaker(name) {
  		var mySpeaker;
  		var speakerTypeMessage;
  		if (name) {
  			var myToken = canvas.tokens.ownedTokens.find(t => t.name == name);
  			var myScene = game.scenes.get(game.user.viewedScene);
  			var myActor = game.actors.getName(name);
  			if (myToken) {
  				mySpeaker = ChatMessage.getSpeaker({ token: myToken });
  				speakerTypeMessage = "[GoDiceRoll] Owned token with name " + name + " found, using for chat message.";
  			} else if (myScene && myActor) {
  				mySpeaker = ChatMessage.getSpeaker({ scene: myScene, actor: myActor });
  				speakerTypeMessage = "[GoDiceRoll] Actor with name " + name + " found, using for chat message.";
  			} else {
  				mySpeaker = ChatMessage.getSpeaker({ user: game.user });
  				mySpeaker.alias = event.name;
  				speakerTypeMessage = "[GoDiceRoll] No token or actor with name " + name + " found, using player with alias for chat message.";
  			}
  		}else {
  			mySpeaker = ChatMessage.getSpeaker({ actor: canvas.tokens.controlled[0].name });
  			mySpeaker.alias = canvas.tokens.controlled[0].name;
  			name = mySpeaker.alias; 
  			speakerTypeMessage = "[GoDiceRoll] Selected token with name " + name + " found, using for chat message.";
  		}
  		console.log("[GoDiceRoll] Received dice roll with alias " + name + ".");
  		console.log(speakerTypeMessage);
  		return mySpeaker;
  	}

  	showRoll(diceId, value, rollEvent) {
  		this.handleRoll(diceId, value, rollEvent);
  	}

  	handleRoll(diceId, value, rollEvent) {
  		let dieType  = this.context.connectedDice.get(diceId).getDieType(true);
  		let dieColor = this.context.connectedDice.get(diceId).getDieColor(true);
  		let dieFaces = this.context.connectedDice.get(diceId).getDieFaces();
  		console.log(rollEvent + " event: ", dieType, dieColor, value);
  		
  		if(value === 1)
  			this.context.connectedDice.get(diceId).pulseLed(5, 30, 20, [255, 0, 0]);
  		if(value === dieFaces)
  			this.context.connectedDice.get(diceId).pulseLed(5, 30, 20, [0, 255, 0]);
  		
  		let diceRollsPrompt = this.context.root.querySelectorAll('form[id^="roll-resolver"]');
  		
  		if (this.context.rollResult?.isEnabled() && diceRollsPrompt && diceRollsPrompt.length > 0){
  			this.populateRollPrompt(diceRollsPrompt, dieType, value);
  		}else {
  			//this.startTimeout(dieType, dieFaces, value);
  			console.log("No Dice Prompt available");
  		}
  	}
  	
  	populateRollPrompt(diceRollsPrompt, dieType, value) {
  				
  		let diceRolls = diceRollsPrompt[0].querySelectorAll('input[data-die="'+dieType.toLowerCase()+'"]');
  		if(!diceRolls || diceRolls.length == 0)	{
  			console.log("No roll required for the type "+dieType.toLowerCase());
  			return;
  		}
  		let flagAssigned = false;
  		for(let r=0;r<diceRolls.length && !flagAssigned; r++) {
  			if(!diceRolls[r]?.value)
  			{
  				diceRolls[r].value = parseInt(value);
  				this.rollFieldUpdate(diceRollsPrompt, diceRolls[r]);
  				flagAssigned = true;
  			}
  		}
  	}
  	
  	rollFieldUpdate(diceRollsPrompt, dieField){
  		console.debug(dieField);
  		const value = Number(dieField.value);
  		const maxValue = Number(dieField.max);
  		if (!(value > 0 && value <= maxValue)) return;

  		let remainRolls = parseInt(diceRollsPrompt[0].getAttribute("data-counter"));
  		
  		this.rollFieldFullfilled(dieField);
  		dieField.setAttribute("data-manual-roll", false);
  		
  		remainRolls--;
  		diceRollsPrompt[0].setAttribute("data-counter", remainRolls);
  		
  		this.sendRolls(diceRollsPrompt);
  	}
  	
  	rollFieldFullfilled(dieField){
  		const value = Number(dieField.value);
  		const maxValue = Number(dieField.max);
  		if(value > 0 && value <= maxValue){
  			dieField.setAttribute('readonly', true);
  			dieField.parentElement.classList.add("fulfilled");
  			dieField.setAttribute("data-manual-roll", true);
  		}
  	}
  	
  	sendRolls(diceRollsPrompt){
  		let remainRolls = parseInt(diceRollsPrompt[0].getAttribute("data-counter"));	
  		if(remainRolls<=0 && this.context.rollResult?.isAutoSendEnabled()) {
  			diceRollsPrompt[0].querySelectorAll("#roll_submit")[0].click();
  		}	
  	}
  	
  	startTimeout(dieType, dieFaces, value) {
  		let die = this.context.rolledDice.get(dieType);
  		if(die){
  			die.number = die.number + 1;
  		}else {
  			if(advdis_modifier.length>0)
  				die = new Die({number:1, faces:dieFaces, modifiers:[advdis_modifier]});	
  			else
  				die = new Die({number:1, faces:dieFaces});
  		}
  		if(parseInt(value) < 0)
  			value = 1;
  		die.results.push({result:parseInt(value), active:true});
  		this.context.rolledDice.set(dieType,die);
  		
  		let bar = this.context.root.querySelectorAll("#round-time-bar");
  		bar[0].classList.remove("round-time-bar");
  		bar[0].offsetWidth;
  		bar[0].classList.add("round-time-bar");
  		this.context.rollTimer = setTimeout(this.rollDice, ROLLED_TIMEOUT);
  	}
  	
  	rollDice() {
  		let plus = new OperatorTerm({operator: "+"});
  		let terms=[];
  		
  		plus._evaluated = true;
  		this.context.rolledDice.forEach((die, diceId) => {
  			console.debug("Evaluate terms for ", diceId, " dice");
  			die._evaluateModifiers();
  			die._evaluated = true;
  			if(terms.length>0)
  				terms.push(plus);
  			terms.push(die);
  		});
  		if(terms.length > 0) {
  			let termMod = new NumericTerm({number:godiceroll_modifier});
  			termMod._evaluated = true;
  			if(godiceroll_modifier>0)
  			{
  				terms.push(plus);
  				terms.push(termMod);
  			}else if(godiceroll_modifier<0){
  				terms.push(termMod);
  			}
  			
  			let r = Roll.fromTerms(terms);
  			r.toMessage({flavor:"<b style =\"font-size:1.5em\">GoDiceRoll</b>"});
  		}
  		this.context.rolledDice.clear();
  	}

  	setDiceBarMaxSlots() {
  		let r = this.context.host;
  		r.style.setProperty('--dicebar-slots', this.getLinkedDice().size + 1);
  	}
  	
  	setCookie(cname, cvalue, exdays) {
  		 const d = new Date();
  		 d.setTime(d.getTime() + (exdays*24*60*60*1000));
  		 let expires = "expires="+ d.toUTCString();
  		 document.cookie = cname + "=" + cvalue + ";" + expires + ";path=/";
  	}
  	
  	getCookie(name) {
  	    var cname = name + "=";
  	    var decodedCookie = decodeURIComponent(document.cookie);
  	    var ca = decodedCookie.split(';');
  	    for(var i = 0; i < ca.length; i++){
  	        var c = ca[i];
  	        while(c.charAt(0) == ' '){
  	            c = c.substring(1);
  	        }
  	        if(c.indexOf(cname) == 0){
  	            return c.substring(cname.length, c.length);
  	        }
  	    }
  	    return "";
  	}
  	
  	injectScript(scripts) {
  		if (scripts.length === 0) {
  			return;
  		}
  		let nextScript = scripts.shift();
  		let s = document.createElement('script');
  		s.src = this.getModulePath()+nextScript.src;
  		s.defer = true;
  		if (nextScript.type !== undefined) {
  			s.setAttribute('type', nextScript.type);
  		}
  		s.onload= () => {
  			console.log("finished injecting ", nextScript.src);
  			this.injectScript(scripts);
  		};
  		console.debug("attempting to append ", nextScript.src);
  		let scriptsSec = document.head.querySelectorAll("script");
  		if(scriptsSec.length > 0){
  			scriptsSec[scriptsSec.length-1].after(s);
  		}else {
  			document.head.appendChild(s);
  		}			
  		//(document.head || document.documentElement).appendChild(s);
  	}
  	
  	 injectStylesheet(stylesheet) {
  		if (stylesheet.length === 0) {
  			return;
  		}
  		stylesheet.forEach((nextStylesheet)=>{
  			let l = document.createElement('link');
  			l.rel = "stylesheet";
  			l.type = "text/css";
  			l.href = this.getModulePath()+nextStylesheet;
  			l.media = "all";
  			console.debug("attempting to append ", nextStylesheet);
  			let links = document.head.querySelectorAll("link");
  			if(links.length > 0){
  				links[links.length-1].after(l);
  			}else {
  				document.head.prepend(l);
  			}
  			//(document.head || document.documentElement).appendChild(l);
  		});
  	}
  	
  	registerHBhelper(){
  		n.registerHelper('eq', (a, b) => a == b);
  		n.registerHelper('noteq', (a, b) => a != b);
  	}
  	
  	getDiceIcons(dieType){
  			return this.context.godiceext.diceIcons[dieType];
  	}
  	
  	getDiceImage(dieType){
  			return this.context.godiceext.diceImages[dieType];
  	}
  	
  	renderTemplate(path, data) {
  	  const template = this.getTemplate(path);
  	  return template(data || {}, {
  	    allowProtoMethodsByDefault: true,
  	    allowProtoPropertiesByDefault: true
  	  });
  	}

  	/**
  	 * Get a template from the server by fetch request and caching the retrieved result
  	 * @param {string} path           The web-accessible HTML template URL
  	 * @param {string} [id]           An ID to register the partial with.
  	 * @returns {Promise<Function>}   A Promise which resolves to the compiled Handlebars template
  	 */
  	getTemplate(path, id) {
  		let htmlString = path;
  		if(!path.startsWith("<!-- Template -->")){
  			if ( path in n.partials ) return n.partials[path];
  			htmlString = this.readSyncFile(path);
  		}else
  			htmlString = htmlString.replace("<!-- Template -->\n","");
  	  const compiled = n.compile(htmlString);
  	  n.registerPartial(id ?? path, compiled);
  	  console.debug(`Retrieved and compiled template ${path}`);
  	  return compiled;
  	}

  	/**
  	 * Get a template from the server by fetch request and caching the retrieved result
  	 * @param {string} path           The web-accessible HTML template URL
  	 */
  	 readSyncFile(path) {
  		const request = new XMLHttpRequest();
  		path = chrome.extension.getURL("path");
  		request.open('GET', path, false);  // `false` makes the request synchronous
  		request.send();
  		return request.responseText;	}

  	async  readAsyncFile(path) {
  		return new Promise((resolve, reject) => {
  			fetch(`${path}`).then(function(response) {
  				response.text().then(function(text) {
  					if(text)
  						resolve(text);
  					else
  						reject(text);
  				});
  			});
  		});
  	}

  	validateHTMLString(string) {
  	    let regexForHTML = /<([A-Za-z][A-Za-z0-9]*)\b[^>]*>(.*?)<\/\1>/;
  	   // check if the regular expression matches the string
  	   let isValid = regexForHTML.test(string);
  	   if (isValid) {
  	      console.debug(string +"\n is a html String");
  	   }else {
  	      console.debug(string +"\n is not a html String");
  	   }
  	   return isValid;
  	}	
  }

  class Popup {
      // build popup with parameters
      constructor(params = {}) {
          this.params = params;
          this.init();
      }

      init() {
          // assign parameters with default values
          this.id = this.params.id ?? "popup";
          this.title = this.params.title ?? "Popup Title";
          this.content = this.params.content ?? "Popup Content";
          this.titleColor = this.params.titleColor ?? "#000000";
          this.backgroundColor = this.params.backgroundColor ?? "#ffffff";
          this.closeColor = this.params.closeColor ?? "#000000";
          this.textColor = this.params.textColor ?? "#000000";
          this.linkColor = this.params.linkColor ?? "#383838";
          this.widthMultiplier = this.params.widthMultiplier ?? 1;
          this.heightMultiplier = this.params.heightMultiplier ?? 0.66;
          this.fontSizeMultiplier = this.params.fontSizeMultiplier ?? 1;
          this.borderRadius = this.params.borderRadius ?? "15px";
          this.sideMargin = this.params.sideMargin ?? "3%";
          this.titleMargin = this.params.titleMargin ?? "2%";
          this.lineSpacing = this.params.lineSpacing ?? "auto";
          this.showImmediately = this.params.showImmediately ?? false;
          this.showOnce = this.params.showOnce ?? false;
          this.fixedHeight = this.params.fixedHeight ?? false;
          this.allowClose = this.params.allowClose ?? true;
          this.underlineLinks = this.params.underlineLinks ?? false;
          this.fadeTime = this.params.fadeTime ?? "0.3s";
          this.buttonWidth = this.params.buttonWidth ?? "fit-content";
          this.borderWidth = this.params.borderWidth ?? "0";
          this.borderColor = this.params.borderColor ?? "#000000";
          this.disableScroll = this.params.disableScroll ?? true;
          this.textShadow = this.params.textShadow ?? "none";
          this.hideCloseButton = this.params.hideCloseButton ?? false;
          this.hideTitle = this.params.hideTitle ?? false;

          // height and width calculations
          this.height = `min(${770 * this.heightMultiplier}px, ${90 * this.heightMultiplier}vw)`;
          this.width = `min(${770 * this.widthMultiplier}px, ${90 * this.widthMultiplier}vw)`;

          // font size calculation
          this.fontSize = `min(${25 * this.fontSizeMultiplier}px, ${4 * this.fontSizeMultiplier}vw)`;

          // create style tag https://stackoverflow.com/a/524721/19271522
          this.css = this.params.css ?? "";
          this.css += `
        .popup.${this.id} {
            transition-duration: ${this.fadeTime};
            text-shadow: ${this.textShadow};
            font-family: '${this.params.font ?? "Inter"}', 'Inter', Helvetica, sans-serif;
        }
        
        .popup.${this.id} .popup-content {
            background-color: ${this.backgroundColor};
            width: ${this.width}; 
            height: ${this.fixedHeight ? this.height : "unset"};
            border-radius: ${this.borderRadius};
            border: ${this.borderWidth} solid ${this.borderColor};
        }

        .popup.${this.id} .popup-header {
            margin-bottom: ${this.titleMargin};
        }

        .popup.${this.id} .popup-title {
            color: ${this.titleColor};
        }

        .popup.${this.id} .popup-close {
            color: ${this.closeColor};
        }

        .popup.${this.id} .popup-body {
            color: ${this.textColor};
            margin-left: ${this.sideMargin};
            margin-right: ${this.sideMargin};
            line-height: ${this.lineSpacing};
            font-size: ${this.fontSize};
        }

        .popup.${this.id} .popup-body button { 
            width: ${this.buttonWidth}; 
        }

        .popup.${this.id} .popup-body a { 
            color: ${this.linkColor};
            ${this.underlineLinks ? "text-decoration: underline;" : ""}
        }`;

          const head = this.params.context?.root ?? document.head;
          const style = document.createElement("style");
          head.append(style);
          this.styleEl = style;
          style.appendChild(document.createTextNode(this.css));

          // process input text
          this.content = this.content.split("\n");
          for (let i = 0; i < this.content.length; i++) {
              let line = this.content[i].trim();
              if (line === "") continue;
              // add <p>
              if (line.includes("§")) {
                  const split = line.split("§");
                  line = `<p class="${split[0].trim()}">${split[1].trim()}</p>`;
              } else if (!this.params.htmlcontent) {
                  line = `<p>${line}</p>`;
              }

              // replace two spaces with nbsps
              line = line.replace(/  /g, "&nbsp;&nbsp;");

              /* ------- Reduced element formatting ------- */

              // a
              while (/{a-(.*?)}\[(.*?)]/.test(line)) line = line.replace(/{a-(.*?)}\[(.*?)]/g, '<a href="$1" target="_blank">$2</a>');

              // button
              while (/{btn-(.*?)}\[(.*?)]/.test(line)) line = line.replace(/{btn-(.*?)}\[(.*?)]/g, '<button class="$1">$2</button>');

              // reduced style formatting
              line = line
                  .replace(/([^\\]?){/g, '$1<span class="')
                  .replace(/([^\\]?)}\[/g, '$1">')
                  .replace(/([^\\]?)]/g, "$1</span>");

              this.content[i] = line;
          }
          this.content = this.content.join("");

          // create popup
          this.popupEl = document.createElement("div");
          this.popupEl.classList.add("popup");
          this.popupEl.classList.add(this.id);
          this.popupEl.innerHTML = `
        <div class="popup-content">
            <div class="popup-header">
                ${
                    /* only add title if hideTitle is off */
                    this.hideTitle ? "" : `<div class="popup-title">${this.title}</div>`
                }
                ${
                    /* only add close button if allowClose is on and hideCloseButton is off */
                    this.allowClose && !this.hideCloseButton ? '<div class="popup-close">&times;</div>' : ""
                }
            </div>
            <div class="popup-body">${this.content}</div>
        </div>`;
          (this.params.context?.root ?? document.body).appendChild(this.popupEl);

          this.popupEl.addEventListener("click", (e) => {
              if (e.target.className == "popup-close" || e.target.classList.contains("popup")) {
                  // don't close if not allowed
                  if (!this.allowClose) return;
                  // close popup
                  this.hide();
              }
          });

          // run load callback if specified
          if (this.params.loadCallback && typeof this.params.loadCallback == "function") {
              this.params.loadCallback(this);
          }

          // show popup (with no animation) if enabled
          if (this.showImmediately) {
              // check for local storage (already closed once)
              if (this.showOnce && localStorage) {
                  if (localStorage.getItem("popup-" + this.id)) {
                      return;
                  }
              }
              this.popupEl.classList.add("fade-in");

          }

          // hide popup on escape key press
          this.listenerController = new AbortController();
          (this.params.context?.root ?? document).addEventListener("keydown", (e) => {
              if (e.key === "Escape") {
                  // don't close if not allowed
                  if (!this.allowClose) return;
                  // close popup
                  this.hide();
              }
          }, { signal: this.listenerController.signal });
      }

      show() {
          this.popupEl.classList.remove("fade-out");
          this.popupEl.classList.add("fade-in");
          this.popupEl.querySelector('input:not([hidden]), select, button')?.focus();
      }

      hide() {
          this.popupEl.classList.remove("fade-in");
          this.popupEl.classList.add("fade-out");
          // remember for next time
          if (localStorage && this.showOnce) {
              localStorage.setItem("popup-" + this.id, true);
          }
          postHide(this);
      }
  }

  function postHide(popup) {
      // call hide callback if set
      if (popup.params.hideCallback && typeof popup.params.hideCallback == "function") {
          popup.params.hideCallback(popup);
      }

  }

  class Dialog extends Popup{
  		
  	constructor(params = {}) {
  		params.id = params.id ?? "dialog";
  		params.loadCallback = (popup) => { 
  			console.debug("Popup ",popup.id," Loaded");
  		};
  		params.hideCallback = (popup) => {
  			popup.popupEl.remove();
              popup.styleEl?.remove();
              popup.listenerController?.abort();
              params.context?.dialogs.delete(popup);
  			if (!this.data) this.cancel = true;
              if (this.cancel) this.rejectPending?.(new GoDiceCancelledError());
              else this.resolvePending?.(this.data);
  			console.debug("Popup closed!");
  		};
  		params.htmlcontent = Dialog.prototype.validateHTMLString(params.content);
  		super(params);
  		this.data = null;
  		this.cancel = null;
  		this.popupEl.id = this.id;
          params.context?.dialogs.add(this);
  		if(params.background) this.popupEl.getElementsByClassName("popup-content")[0].style.background = params.background;
  		var form = this.popupEl.querySelectorAll("form")[0];
  		form?.addEventListener("submit", this.handleSubmit.bind(this));
  		var popupclose = this.popupEl.querySelectorAll(".popup-close")[0];
  		popupclose?.addEventListener("click", this.handleSubmit.bind(this));
  	}
  	
  	show(){
  		super.show();
  		if (!this.pending) this.pending = new Promise((resolve, reject) => {
              this.resolvePending = resolve;
              this.rejectPending = reject;
              if (this.data) resolve(this.data);
              else if (this.cancel) reject(new GoDiceCancelledError());
          });
          return this.pending;
  	}
  		
  	close(data){
  		this.data = data;
  		this.hide();
  	}
  	
  	handleSubmit(event) {
  		event.preventDefault();
  		this.close(event.target);
  	}
  	
   cancelOperation() {
    this.cancel = true;
    this.rejectPending?.(new GoDiceCancelledError());
    // Each cleanup runs even if another DOM operation fails.
    for (const action of [() => this.popupEl.remove(), () => this.styleEl?.remove(),
     () => this.listenerController?.abort(), () => this.params.context?.dialogs.delete(this)]) {
     try { action(); } catch (error) { console.warn('GoDice dialog cleanup failed:', error); }
    }
   }

  	validateHTMLString(string) {
  	    let regexForHTML = /<([A-Za-z][A-Za-z0-9]*)\b[^>]*>(.*?)<\/\1>/;
  	   // check if the regular expression matches the string
  	   let isValid = regexForHTML.test(string);
  	   if (isValid) {
  	      console.debug(string +"\n is a html String");
  	   }else {
  	      console.debug(string +"\n is not a html String");
  	   }
  	   return isValid;
  	}	
  	
  }

